import mongoose from 'mongoose';

const { ObjectId } = mongoose.Schema.Types;

// Group chat lives in its own collection so the group document stays small and
// history can be paginated independently of the member, session and file lists.
const groupMessageSchema = new mongoose.Schema(
  {
    groupe: { type: ObjectId, ref: 'Groupe', required: true },
    auteur: { type: ObjectId, ref: 'Utilisateur', required: true },
    contenu: { type: String, required: true, trim: true, maxlength: 2000 },
    // Generated by the sender's client; makes resends after a reconnect idempotent.
    clientId: { type: String, required: true, maxlength: 64 },
  },
  { timestamps: { createdAt: 'dateEnvoi', updatedAt: false } },
);

groupMessageSchema.index({ groupe: 1, dateEnvoi: -1 });
groupMessageSchema.index({ groupe: 1, auteur: 1, clientId: 1 }, { unique: true });

export const GroupMessage = mongoose.model('MessageGroupe', groupMessageSchema, 'messages_groupes');
